/* MKSTOOR — Stage 3: bitmap font blitter (see mkstoor/font.h).
 *
 * The glyph table itself lives in ui/font_data.c and is generated by
 * tools/gen_font.py; this file only interprets it. Drawing goes through
 * mks_gop_put() so every pixel format / BltOnly quirk is handled once,
 * in core/gop.c. A future PSF loader (Stage 4) will install a different
 * `struct mks_font` without touching any call site.
 */
#include <mkstoor/font.h>

/* Generated table: MKS_FONT_GLYPH_COUNT glyphs x 6 columns. */
#define MKS_FONT_GLYPH_COUNT 95
extern const u8 mks_font_builtin_bits[MKS_FONT_GLYPH_COUNT][6];

static const struct mks_font g_builtin = {
        .name   = "mkstoor-6x8",
        .width  = MKS_FONT_WIDTH,
        .height = MKS_FONT_HEIGHT,
        .bits   = (const u8 *)mks_font_builtin_bits,
};

const struct mks_font *mks_font_builtin(void)
{
        return &g_builtin;
}

/* Draw the replacement box for codepoints outside the covered range:
 * a hollow rectangle so missing glyphs are obvious on screen but never
 * crash or silently skip. */
static void draw_replacement(u32 x, u32 y, mks_rgb_t fg, mks_rgb_t bg)
{
        for (u32 row = 0; row < MKS_FONT_HEIGHT; row++)
                for (u32 col = 0; col < MKS_FONT_WIDTH; col++) {
                        bool edge = row == 1 || row == MKS_FONT_HEIGHT - 2 ||
                                    col == 1 || col == MKS_FONT_WIDTH - 2;
                        mks_gop_put(x + col, y + row, edge ? fg : bg);
                }
}

void mks_font_draw_char(const struct mks_font *f, u32 x, u32 y,
                        char c, mks_rgb_t fg, mks_rgb_t bg)
{
        if (!f || !f->bits)
                return;
        u8 code = (u8)c;
        if (code < MKS_FONT_FIRST || code > MKS_FONT_LAST) {
                draw_replacement(x, y, fg, bg);
                return;
        }
        const u8 *glyph = f->bits +
                          (usize)(code - MKS_FONT_FIRST) * f->width;
        for (u32 col = 0; col < f->width; col++) {
                u8 bits = glyph[col];
                for (u32 row = 0; row < f->height; row++)
                        mks_gop_put(x + col, y + row,
                                    (bits & (1u << row)) ? fg : bg);
        }
}

u32 mks_font_draw_text(const struct mks_font *f, u32 x, u32 y,
                       const char *s, mks_rgb_t fg, mks_rgb_t bg, u32 max_w)
{
        if (!f || !s)
                return 0;
        u32 adv = 0;
        while (*s) {
                if (max_w && adv + f->width > max_w)
                        break;                 /* clipped: caller pads */
                mks_font_draw_char(f, x + adv, y, *s, fg, bg);
                adv += f->width;
                s++;
        }
        return adv;
}

u32 mks_font_text_width(const struct mks_font *f, const char *s)
{
        if (!f || !s)
                return 0;
        u32 n = 0;
        while (s[n])
                n++;
        return n * f->width;
}

u32 mks_font_line_height(const struct mks_font *f, u32 scale)
{
        if (!f)
                return 0;
        return f->height * MAX(scale, 1);
}
